1	import type { LoadedAssets } from './assets.js';
2	import type { BlockRegistry, BlockDef } from './blocks.js';
3	import type { World } from './world.js';
4	import type { Player } from './player.js';
5	import type { Renderer } from './renderer.js';
6	import { BlockIconRenderer } from './blockIcons.js';
7	import { clamp } from './math.js';
8	
9	const COLORS = {
10	  white: '#ffffff',
11	  gray: '#aaaaaa',
12	  darkGray: '#555555',
13	  yellow: '#ffff55',
14	  green: '#55ff55',
15	  red: '#ff5555',
16	  aqua: '#55ffff',
17	};
18	
19	function titleCase(s: string): string {
20	  return s.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
21	}
22	
23	export class Hud {
24	  private ctx: CanvasRenderingContext2D;
25	  private scale = 3;
26	  private guiW = 640;
27	  private guiH = 360;
28	  private uiDpr = 1;
29	  private uiScale = 3;
30	  private iconPx = 48;
31	  private icons = new Map<string, HTMLCanvasElement>();
32	  private iconRenderer: BlockIconRenderer;
33	  private underwaterPattern: CanvasPattern | null = null;
34	  inventoryOpen = false;
35	  inventoryPage = 0;
36	  private invCategory = 0;
37	  private invScrollRow = 0;
38	  private survivalView = false;
39	  private carriedId = 0;
40	  private hoverTab = -1;
41	  private noticeText = '';
42	  private noticeUntil = 0;
43	  private mouseCss = { x: 0, y: 0 };
44	  private invBlocks: BlockDef[];
45	  private categories: { name: string; items: BlockDef[]; top: boolean; index: number; icon: string }[] = [];
46	
47	  constructor(private canvas: HTMLCanvasElement, private assets: LoadedAssets, private rocks: BlockRegistry, private world: World) {
48	    const ctx = canvas.getContext('2d')!;
49	    ctx.imageSmoothingEnabled = false;
50	    this.ctx = ctx;
51	    this.invBlocks = rocks.blocks.filter(b => b.id > 0);
52	    this.iconRenderer = new BlockIconRenderer(assets);
53	    this.buildCategories();
54	    try {
55	      this.underwaterPattern = ctx.createPattern(assets.env.underwater, 'repeat');
56	    } catch { /* ignore */ }
57	  }
58	
59	  resize(cssW: number, cssH: number): void {
60	    this.scale = clamp(Math.floor(Math.min(cssW / 320, cssH / 240)), 2, 4);
61	    this.guiW = Math.ceil(cssW / this.scale);
62	    this.guiH = Math.ceil(cssH / this.scale);
63	    this.uiDpr = Math.min(window.devicePixelRatio || 1, 1.5);
64	    this.uiScale = this.scale * this.uiDpr;
65	    this.iconPx = Math.max(16, Math.min(160, Math.round(16 * this.uiScale)));
66	    this.canvas.width = Math.max(1, Math.round(cssW * this.uiDpr));
67	    this.canvas.height = Math.max(1, Math.round(cssH * this.uiDpr));
68	    this.canvas.style.width = cssW + 'px';
69	    this.canvas.style.height = cssH + 'px';
70	    this.ctx.setTransform(this.uiScale, 0, 0, this.uiScale, 0, 0);
71	    this.ctx.imageSmoothingEnabled = false;
72	    this.icons.clear();
73	  }
74	
75	  private buildCategories(): void {
76	    const find = (names: string[]) => names
77	      .map(n => this.rocks.byName.get(n))
78	      .filter((b): b is BlockDef => !!b);
79	    const groups: [string, string[]][] = [
80	      ['Building Blocks', ['stone', 'cobblestone', 'mossy_cobblestone', 'stone_bricks', 'mossy_stone_bricks', 'cracked_stone_bricks',
81	        'bricks', 'deepslate', 'cobbled_deepslate', 'polished_deepslate', 'granite', 'diorite', 'andesite', 'tuff', 'calcite',
82	        'smooth_stone', 'sandstone', 'red_sandstone', 'glass', 'oak_planks', 'oak_stairs', 'oak_slab', 'birch_planks', 'birch_stairs',
83	        'birch_slab', 'spruce_planks', 'spruce_stairs', 'spruce_slab', 'sulfur', 'sulfur_bricks', 'polished_sulfur', 'chiseled_sulfur',
84	        'snow_block', 'ice', 'obsidian']],
85	      ['Colored Blocks', ['cinnabar', 'cinnabar_bricks', 'polished_cinnabar', 'chiseled_cinnabar', 'potent_sulfur']],
86	      ['Natural Blocks', ['grass_block', 'dirt', 'coarse_dirt', 'rooted_dirt', 'podzol', 'sand', 'red_sand', 'gravel', 'clay',
87	        'oak_log', 'birch_log', 'spruce_log', 'oak_leaves', 'birch_leaves', 'spruce_leaves', 'coal_ore', 'iron_ore', 'copper_ore',
88	        'gold_ore', 'diamond_ore', 'emerald_ore', 'bedrock', 'snow', 'moss_block', 'cactus', 'short_grass', 'fern', 'dead_bush',
89	        'poppy', 'dandelion', 'cornflower', 'azure_bluet', 'oxeye_daisy', 'allium', 'lily_of_the_valley', 'sulfur_spike', 'water', 'lava']],
90	      ['Functional Blocks', ['crafting_table', 'bookshelf', 'torch', 'lantern', 'glowstone', 'sea_lantern']],
91	      ['Redstone Blocks', []],
92	      ['Tools & Utilities', []],
93	      ['Combat', []],
94	    ];
95	    this.categories = groups.map(([name, names], index) => ({
96	      name, items: find(names), top: true, index: index + 1,
97	      icon: names[0] ?? 'stone',
98	    }));
99	    const bottom: [string, string[], string][] = [
100	      ['Food & Drinks', [], 'poppy'],
101	      ['Ingredients', ['coal_ore', 'iron_ore', 'copper_ore', 'gold_ore', 'diamond_ore', 'emerald_ore'], 'coal_ore'],
102	      ['Spawn Eggs', [], 'sulfur_spike'],
103	      ['Search Items', this.rocks.blocks.filter(b => b.id > 0).map(b => b.name), 'glass'],
104	      ['Survival Inventory', [], 'crafting_table'],
105	    ];
106	    for (let i = 0; i < bottom.length; i++) {
107	      const [name, names, icon] = bottom[i];
108	      this.categories.push({ name, items: find(names), top: false, index: i + 1, icon });
109	    }
110	  }
111	
112	  private blockIcon(def: BlockDef): HTMLCanvasElement {
113	    const key = `${def.id}|${def.tintMode}|${def.tintColor.join(',')}|${this.iconPx}`;
114	    const cached = this.icons.get(key);
115	    if (cached) return cached;
116	    const icon = this.iconRenderer.render(def, this.iconPx);
117	    this.icons.set(key, icon);
118	    return icon;
119	  }
120	
121	  setInventory(open: boolean, page?: number): void {
122	    this.inventoryOpen = open;
123	    if (open && page != null) this.inventoryPage = page;
124	    if (!open) this.carriedId = 0;
125	  }
126	
127	  setCarried(id: number): void {
128	    this.carriedId = id;
129	  }
130	
131	  getCarried(): number {
132	    return this.carriedId;
133	  }
134	
135	  clearCarried(): void {
136	    this.carriedId = 0;
137	  }
138	
139	  inventoryScroll(delta: number): void {
140	    if (!this.inventoryOpen) return;
141	    const items = this.activeCategory().items;
142	    const max = Math.max(0, Math.ceil(items.length / 9) - 5);
143	    this.invScrollRow = clamp(this.invScrollRow + Math.sign(delta), 0, max);
144	  }
145	
146	  cycleCategory(dir: number): void {
147	    if (!this.categories.length) return;
148	    this.invCategory = (this.invCategory + dir + this.categories.length) % this.categories.length;
149	    this.invScrollRow = 0;
150	    this.survivalView = this.categories[this.invCategory]?.name === 'Survival Inventory';
151	    this.carriedId = 0;
152	  }
153	
154	  private activeCategory() {
155	    return this.categories[this.invCategory] ?? this.categories[0];
156	  }
157	
158	  setMouse(cssX: number, cssY: number): void {
159	    this.mouseCss.x = cssX;
160	    this.mouseCss.y = cssY;
161	  }
162	
163	  hotbarHit(cssX: number, cssY: number): number {
164	    const gx = cssX / this.scale;
165	    const gy = cssY / this.scale;
166	    const hotbarX = Math.floor((this.guiW - 182) / 2);
167	    const hotbarY = this.guiH - 22;
168	    if (gx < hotbarX || gx >= hotbarX + 182 || gy < hotbarY - 2 || gy >= hotbarY + 22) return -1;
169	    return clamp(Math.floor((gx - hotbarX) / 20), 0, 8);
170	  }
171	
172	  toast(text: string): void {
173	    this.noticeText = text;
174	    this.noticeUntil = performance.now() + 1600;
175	  }
176	
177	  private creativeLayout() {
178	    const cols = 9, rows = 5, slot = 18, panelW = 195, panelH = 136;
179	    const x = Math.floor((this.guiW - panelW) / 2);
180	    const y = Math.floor((this.guiH - panelH) / 2);
181	    return {
182	      cols, rows, slot, w: panelW, h: panelH, x, y,
183	      gridX: x + 9, gridY: y + 18, hotbarY: y + 112,
184	    };
185	  }
186	
187	  private iconForName(name: string | null): HTMLCanvasElement | null {
188	    if (!name) return null;
189	    const def = this.rocks.byName.get(name);
190	    return def ? this.blockIcon(def) : null;
191	  }
192	
193	  private tabRects(): { cat: number; x: number; y: number; w: number; h: number; top: boolean; index: number }[] {
194	    const L = this.creativeLayout();
195	    const rects: { cat: number; x: number; y: number; w: number; h: number; top: boolean; index: number }[] = [];
196	    const tops = this.categories.filter(c => c.top);
197	    for (let i = 0; i < tops.length; i++) {
198	      rects.push({ cat: this.categories.indexOf(tops[i]), x: L.x + 7 + i * 26, y: L.y - 28, w: 26, h: 32, top: true, index: tops[i].index });
199	    }
200	    const bottoms = this.categories.filter(c => !c.top);
201	    for (let i = 0; i < bottoms.length; i++) {
202	      rects.push({ cat: this.categories.indexOf(bottoms[i]), x: L.x + 6 + i * 26, y: L.y + L.h - 4, w: 26, h: 32, top: false, index: bottoms[i].index });
203	    }
204	    return rects;
205	  }
206	
207	  private closeRect() {
208	    const L = this.creativeLayout();
209	    return { x: L.x + L.w - 18, y: L.y + L.h + 2, w: 14, h: 14 };
210	  }
211	
212	  inventoryHit(cssX: number, cssY: number): { block: number } | { hotbar: number } | { category: number } | { close: true } | { scroll: true } | null {
213	    if (!this.inventoryOpen) return null;
214	    const gx = cssX / this.scale, gy = cssY / this.scale;
215	    const L = this.creativeLayout();
216	    const touchUi = (navigator.maxTouchPoints || 0) > 0;
217	    if (touchUi) {
218	      const c = this.closeRect();
219	      if (gx >= c.x && gx < c.x + c.w && gy >= c.y && gy < c.y + c.h) return { close: true };
220	    }
221	    for (const t of this.tabRects()) {
222	      if (gx >= t.x && gx < t.x + t.w && gy >= t.y && gy < t.y + t.h) {
223	        this.invCategory = t.cat;
224	        this.invScrollRow = 0;
225	        this.survivalView = this.categories[t.cat]?.name === 'Survival Inventory';
226	        this.carriedId = 0;
227	        return { category: t.cat };
228	      }
229	    }
230	    if (gx >= L.x && gx < L.x + L.w && gy >= L.y && gy < L.y + L.h) {
231	      if (this.survivalView) {
232	        if (gx >= L.x + 173 && gy >= L.y + 112) return { close: true };
233	        const slot = Math.floor((gx - (L.x + 9)) / L.slot);
234	        if (slot >= 0 && slot < 9 && gy >= L.hotbarY && gy < L.hotbarY + 18) return { hotbar: slot };
235	        return null;
236	      }
237	      const col = Math.floor((gx - L.gridX) / L.slot);
238	      const row = Math.floor((gy - L.gridY) / L.slot);
239	      if (col >= 0 && col < 9 && row >= 0 && row < 5) {
240	        const items = this.activeCategory().items;
241	        const idx = this.invScrollRow * 9 + row * 9 + col;
242	        if (idx < items.length) {
243	          this.carriedId = items[idx].id;
244	          return { block: items[idx].id };
245	        }
246	      }
247	      const slot = Math.floor((gx - (L.x + 9)) / L.slot);
248	      if (slot >= 0 && slot < 9 && gy >= L.hotbarY && gy < L.hotbarY + 18) return { hotbar: slot };
249	      if (gx >= L.x + 175 && gx < L.x + 187 && gy >= L.y + 18 && gy < L.y + 108) {
250	        const max = Math.max(0, Math.ceil(this.activeCategory().items.length / 9) - 5);
251	        if (max > 0) {
252	          this.invScrollRow = clamp(Math.round(((gy - (L.y + 18)) / 90) * max), 0, max);
253	          return { scroll: true };
254	        }
255	      }
256	      return null;
257	    }
258	    return null;
259	  }
260	
261	  private drawInventory(player: Player): void {
262	    const { ctx, assets } = this;
263	    const L = this.creativeLayout();
264	    const gx = this.mouseCss.x / this.scale;
265	    const gy = this.mouseCss.y / this.scale;
266	    const category = this.activeCategory();
267	    const items = category.items;
268	    const maxScroll = Math.max(0, Math.ceil(items.length / 9) - 5);
269	    this.invScrollRow = clamp(this.invScrollRow, 0, maxScroll);
270	
271	    const panel = this.survivalView ? assets.gui.creativeInventory : assets.gui.creativeItems;
272	    if (panel) ctx.drawImage(panel, 0, 0, 195, 136, L.x, L.y, 195, 136);
273	    else {
274	      ctx.fillStyle = '#c6c6c6';
275	      ctx.fillRect(L.x, L.y, L.w, L.h);
276	    }
277	
278	    // Official tab sprites sit around the panel; the active tab is drawn last.
279	    this.hoverTab = -1;
280	    const tabList = this.tabRects().sort((a, b) => Number(a.cat === this.invCategory) - Number(b.cat === this.invCategory));
281	    for (const t of tabList) {
282	      const selected = t.cat === this.invCategory;
283	      const key = `${t.top ? 'tabTop' : 'tabBottom'}${selected ? 'Selected' : 'Unselected'}${t.index}`;
284	      const tab = assets.gui[key];
285	      if (tab) ctx.drawImage(tab, t.x, t.y, 26, 32);
286	      const icon = this.iconForName(this.categories[t.cat]?.icon ?? null);
287	      if (icon) ctx.drawImage(icon, t.x + 5, t.y + 8, 16, 16);
288	      if (gx >= t.x && gx < t.x + t.w && gy >= t.y && gy < t.y + t.h) this.hoverTab = t.cat;
289	    }
290	
291	    const first = this.invScrollRow * 9;
292	    let hovered: BlockDef | null = null;
293	    if (!this.survivalView) {
294	      for (let i = 0; i < 45; i++) {
295	        const idx = first + i;
296	        if (idx >= items.length) break;
297	        const col = i % 9, row = (i / 9) | 0;
298	        const sx = L.gridX + col * 18, sy = L.gridY + row * 18;
299	        const hov = gx >= sx && gx < sx + 18 && gy >= sy && gy < sy + 18;
300	        if (hov) {
301	          ctx.fillStyle = 'rgba(255,255,255,0.55)';
302	          ctx.fillRect(sx + 1, sy + 1, 16, 16);
303	          hovered = items[idx];
304	        }
305	        const icon = this.blockIcon(items[idx]);
306	        ctx.drawImage(icon, sx + 1, sy + 1, 16, 16);
307	      }
308	    }
309	
310	    // Player hotbar row in the creative panel.
311	    for (let i = 0; i < 9; i++) {
312	      const def = player.hotbar[i];
313	      if (!def) continue;
314	      const sx = L.x + 9 + i * 18, sy = L.hotbarY;
315	      const icon = this.blockIcon(def);
316	      ctx.drawImage(icon, sx + 1, sy + 1, 16, 16);
317	      if (gx >= sx && gx < sx + 18 && gy >= sy && gy < sy + 18) hovered = def;
318	    }
319	    const selX = L.x + 9 + player.selected * 18;
320	    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
321	    ctx.lineWidth = 1;
322	    ctx.strokeRect(selX + 0.5, L.hotbarY + 0.5, 17, 17);
323	
324	    // Scrollbar.
325	    if (!this.survivalView && maxScroll > 0) {
326	      const frac = this.invScrollRow / maxScroll;
327	      const scroller = assets.gui.creativeScroller;
328	      if (scroller) ctx.drawImage(scroller, L.x + 175, L.y + 18 + Math.round(frac * 75), 12, 15);
329	    }
330	
331	    if (!this.survivalView && (navigator.maxTouchPoints || 0) > 0) {
332	      const c = this.closeRect();
333	      ctx.fillStyle = '#c6c6c6';
334	      ctx.fillRect(c.x, c.y, c.w, c.h);
335	      ctx.fillStyle = '#ffffff';
336	      ctx.fillRect(c.x, c.y, c.w, 1);
337	      ctx.fillStyle = '#555555';
338	      ctx.fillRect(c.x, c.y + c.h - 1, c.w, 1);
339	      assets.font.drawCentered(ctx, 'x', c.x + c.w / 2, c.y + 3, '#3f3f3f', false);
340	    }
341	
342	    const carried = this.carriedId ? this.rocks.get(this.carriedId) : null;
343	    if (carried) {
344	      const icon = this.blockIcon(carried);
345	      ctx.drawImage(icon, gx - 8, gy - 8, 16, 16);
346	    }
347	
348	    let tip = this.survivalView ? '' : (hovered ? titleCase(hovered.name) : '');
349	    if (!tip && this.hoverTab >= 0) tip = this.categories[this.hoverTab]?.name ?? '';
350	    if ((navigator.maxTouchPoints || 0) > 0) tip = '';
351	    if (tip) {
352	      const w = assets.font.width(tip) + 8;
353	      const x = clamp(gx + 10, 0, this.guiW - w);
354	      const y = clamp(gy - 14, 0, this.guiH - 14);
355	      ctx.fillStyle = 'rgba(16,0,16,0.94)';
356	      ctx.fillRect(x, y, w, 13);
357	      ctx.strokeStyle = 'rgba(80,0,255,0.9)';
358	      ctx.lineWidth = 1;
359	      ctx.strokeRect(x + 0.5, y + 0.5, w - 1, 12);
360	      assets.font.draw(ctx, tip, x + 4, y + 3, COLORS.white, false);
361	    }
362	  }
363	
364	  render(state: {
365	    started: boolean;
366	    paused: boolean;
367	    player: Player;
368	    fps: number;
369	    ticks: number;
370	    debug: boolean;
371	    underwater: boolean;
372	    renderer: Renderer;
373	    elapsed: number;
374	    inventoryOpen: boolean;
375	  }): void {
376	    const { ctx, guiW, guiH } = this;
377	    ctx.setTransform(this.uiScale, 0, 0, this.uiScale, 0, 0);
378	    ctx.imageSmoothingEnabled = false;
379	    ctx.clearRect(0, 0, guiW, guiH);
380	    const player = state.player;
381	    if (player.hurtTime > 0) {
382	      ctx.fillStyle = `rgba(190,20,20,${Math.min(0.28, player.hurtTime * 0.55)})`;
383	      ctx.fillRect(0, 0, guiW, guiH);
384	    }
385	
386	    if (state.underwater) {
387	      if (this.underwaterPattern) {
388	        ctx.save();
389	        ctx.globalAlpha = 0.35;
390	        ctx.fillStyle = this.underwaterPattern;
391	        ctx.fillRect(0, 0, guiW, guiH);
392	        ctx.restore();
393	      }
394	      ctx.fillStyle = 'rgba(20,60,140,0.18)';
395	      ctx.fillRect(0, 0, guiW, guiH);
396	    }
397	
398	    if (!state.started) {
399	      this.drawTitle(false);
400	      return;
401	    }
402	
403	    const hotbarX = Math.floor((guiW - 182) / 2);
404	    const hotbarY = guiH - 22;
405	    ctx.drawImage(this.assets.gui.hotbar, hotbarX, hotbarY);
406	    ctx.drawImage(this.assets.gui.hotbarSelection, hotbarX - 1 + player.selected * 20, hotbarY - 1);
407	    for (let i = 0; i < 9; i++) {
408	      const def = player.hotbar[i];
409	      if (!def) continue;
410	      const icon = this.blockIcon(def);
411	      ctx.drawImage(icon, hotbarX + 3 + i * 20, hotbarY + 3, 16, 16);
412	    }
413	
414	    const heartY = hotbarY - 11;
415	    for (let i = 0; i < 10; i++) {
416	      const h = this.assets.gui;
417	      const hx = hotbarX + 2 + i * 8;
418	      if (h.heartContainer) ctx.drawImage(h.heartContainer, hx, heartY, 9, 9);
419	      const hp = player.health - i * 2;
420	      if (hp >= 2 && h.heartFull) ctx.drawImage(h.heartFull, hx, heartY, 9, 9);
421	      else if (hp >= 1 && h.heartHalf) ctx.drawImage(h.heartHalf, hx, heartY, 9, 9);
422	    }
423	
424	    if (!state.inventoryOpen) {
425	      ctx.drawImage(this.assets.gui.crosshair, Math.floor((guiW - 15) / 2), Math.floor((guiH - 15) / 2));
426	    }
427	
428	    const now = performance.now();
429	    if (now - player.selectedSince < 2200) {
430	      const def = player.currentBlock();
431	      if (def) {
432	        const name = titleCase(def.name);
433	        this.assets.font.drawCentered(ctx, name, guiW / 2, hotbarY - 18, COLORS.white, true);
434	      }
435	    }
436	
437	    if (performance.now() < this.noticeUntil && !state.inventoryOpen) {
438	      this.assets.font.drawCentered(ctx, this.noticeText, guiW / 2, 12, COLORS.white, true);
439	    }
440	    if (state.inventoryOpen) this.drawInventory(player);
441	    if (state.debug) this.drawDebug(state);
442	    if (state.paused && !state.inventoryOpen) this.drawTitle(true);
443	  }
444	
445	  private drawTitle(paused: boolean): void {
446	    const { ctx, guiW, guiH, assets } = this;
447	    ctx.fillStyle = 'rgba(0,0,0,0.62)';
448	    ctx.fillRect(0, 0, guiW, guiH);
449	    const logo = assets.gui.title;
450	    if (logo) {
451	      const w = 256, h = 64;
452	      ctx.drawImage(logo, Math.floor((guiW - w) / 2), 28, w, h);
453	    }
454	    assets.font.drawCentered(ctx, 'Java Edition 26.2 · Vanilla assets · WebGL2', guiW / 2, 100, COLORS.gray, true);
455	    const bw = 200, bh = 20;
456	    const bx = Math.floor((guiW - bw) / 2), by = 126;
457	    const btn = paused ? (assets.gui.buttonHighlighted ?? assets.gui.button) : assets.gui.button;
458	    if (btn) ctx.drawImage(btn, bx, by, bw, bh);
459	    else { ctx.fillStyle = '#6f6f6f'; ctx.fillRect(bx, by, bw, bh); }
460	    assets.font.drawCentered(ctx, paused ? 'Resume' : 'Play', guiW / 2, by + 6, COLORS.white, true);
461	
462	    const lines = [
