1	import { loadBitmap } from './gl.js';
2	
3	interface Glyph {
4	  cx: number; cy: number; w: number; h: number; advance: number;
5	}
6	
7	function parseHex(hex: string): [number, number, number] {
8	  const n = parseInt(hex.replace('#', ''), 16);
9	  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
10	}
11	
12	export class VanillaFont {
13	  private atlas: HTMLCanvasElement;
14	  private glyphs = new Map<number, Glyph>();
15	  private tinted = new Map<string, HTMLCanvasElement>();
16	  private shadowTinted = new Map<string, HTMLCanvasElement>();
17	  readonly lineHeight = 9;
18	  readonly height = 8;
19	  spaceAdvance = 4;
20	
21	  private constructor(atlas: HTMLCanvasElement) {
22	    this.atlas = atlas;
23	  }
24	
25	  static async load(manifestFont: Record<string, string>, base: string): Promise<VanillaFont> {
26	    const includeUrl = base + 'font/meta/include/default.json';
27	    const data = await (await fetch(includeUrl)).json();
28	    const provider = data.providers.find((p: any) => typeof p.file === 'string' && p.file.includes('ascii.png'));
29	    if (!provider) throw new Error('ascii font provider not found');
30	    const spaceData = await (await fetch(base + 'font/meta/include/space.json')).json().catch(() => null);
31	    const spaceProvider = spaceData?.providers?.find((p: any) => p.type === 'space');
32	    const bmp = await loadBitmap(base + 'font/textures/ascii.png');
33	    const canvas = document.createElement('canvas');
34	    canvas.width = bmp.width;
35	    canvas.height = bmp.height;
36	    const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
37	    ctx.imageSmoothingEnabled = false;
38	    ctx.drawImage(bmp, 0, 0);
39	    const image = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
40	    const font = new VanillaFont(canvas);
41	    if (spaceProvider?.advances?.[' '] != null) font.spaceAdvance = spaceProvider.advances[' '];
42	
43	    const cellW = 8;
44	    const cellH = 8;
45	    const cols = Math.floor(canvas.width / cellW);
46	    provider.chars.forEach((row: string, rowIndex: number) => {
47	      for (let col = 0; col < row.length; col++) {
48	        const cp = row.charCodeAt(col);
49	        if (!cp) continue;
50	        const x0 = col * cellW;
51	        const y0 = rowIndex * cellH;
52	        let maxX = -1;
53	        for (let y = 0; y < cellH; y++) {
54	          for (let x = 0; x < cellW; x++) {
55	            if (image[((y0 + y) * canvas.width + (x0 + x)) * 4 + 3] > 8 && x > maxX) maxX = x;
56	          }
57	        }
58	        const advance = Math.max(1, maxX + 2);
59	        font.glyphs.set(cp, { cx: x0, cy: y0, w: cellW, h: cellH, advance });
60	      }
61	    });
62	    if (font.glyphs.has(32)) font.glyphs.get(32)!.advance = font.spaceAdvance;
63	    return font;
64	  }
65	
66	  width(text: string): number {
67	    let w = 0;
68	    for (const ch of text) {
69	      const cp = ch.codePointAt(0)!;
70	      if (ch === ' ') { w += this.spaceAdvance; continue; }
71	      const g = this.glyphs.get(cp);
72	      w += g ? g.advance : 6;
73	    }
74	    return w;
75	  }
76	
77	  private getAtlas(color: string): HTMLCanvasElement {
78	    let c = this.tinted.get(color);
79	    if (c) return c;
80	    c = document.createElement('canvas');
81	    c.width = this.atlas.width;
82	    c.height = this.atlas.height;
83	    const ctx = c.getContext('2d')!;
84	    ctx.imageSmoothingEnabled = false;
85	    ctx.drawImage(this.atlas, 0, 0);
86	    ctx.globalCompositeOperation = 'source-in';
87	    ctx.fillStyle = color;
88	    ctx.fillRect(0, 0, c.width, c.height);
89	    this.tinted.set(color, c);
90	    return c;
91	  }
92	
93	  private getShadowAtlas(color: string): HTMLCanvasElement {
94	    let c = this.shadowTinted.get(color);
95	    if (c) return c;
96	    const [r, g, b] = parseHex(color);
97	    const shadow = `rgb(${Math.floor(r * 0.25)},${Math.floor(g * 0.25)},${Math.floor(b * 0.25)})`;
98	    c = this.getAtlas(shadow);
99	    this.shadowTinted.set(color, c);
100	    return c;
